import{_ as a,o as r,c as t,ag as o}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"🔬 科学快报 | 2026年10月2日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-10-02.md","filePath":"science-log/src/reconstructed/2026-10-02.md"}'),n={name:"science-log/src/reconstructed/2026-10-02.md"};function s(i,e,c,l,d,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="🔬-科学快报-2026年10月2日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年10月2日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年10月2日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年10月2日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 ｜ 重建日：2026-11-05</p></blockquote><hr><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧬-胰腺癌对-car-t-疗法的敏感性-由肿瘤细胞自身的应激状态决定" tabindex="-1">🧬 胰腺癌对 CAR-T 疗法的敏感性，由肿瘤细胞自身的应激状态决定 <a class="header-anchor" href="#🧬-胰腺癌对-car-t-疗法的敏感性-由肿瘤细胞自身的应激状态决定" aria-label="Permalink to &quot;🧬 胰腺癌对 CAR-T 疗法的敏感性，由肿瘤细胞自身的应激状态决定&quot;">​</a></h3><p><strong>Tumor cell–intrinsic stress states drive sensitivity to CAR T cell therapy in pancreatic cancer</strong><em>Science Advances (2026)</em></p><p>CAR-T 疗法在血液肿瘤中大获成功，却在包括胰腺导管腺癌（PDAC）在内的实体瘤中收效甚微，原因长期不明。研究团队把模块化体内 CRISPR 筛选、单细胞基因组学与免疫健全小鼠模型整合起来，系统寻找决定 CAR-T 应答的肿瘤内在因子。结果显示，肿瘤细胞自身的&quot;应激状态&quot;（stress states）是敏感性的关键变量——处于特定应激程序下的肿瘤细胞更容易被 CAR-T 杀伤，而不是传统认为的抗原表达量单一决定。这为实体瘤 CAR-T 提供了一个可干预的分子开关：与其堆砌抗原，不如调控肿瘤的应激通路。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aeh8973" target="_blank" rel="noreferrer">10.1126/sciadv.aeh8973</a></p><hr><h3 id="🩸-神经元胞外囊泡的电子剖析-实现帕金森病早期预测" tabindex="-1">🩸 神经元胞外囊泡的电子剖析，实现帕金森病早期预测 <a class="header-anchor" href="#🩸-神经元胞外囊泡的电子剖析-实现帕金森病早期预测" aria-label="Permalink to &quot;🩸 神经元胞外囊泡的电子剖析，实现帕金森病早期预测&quot;">​</a></h3><p><strong>Electronic profiling of neuronal extracellular vesicles enables early prediction of Parkinson&#39;s disease</strong><em>Science Advances (2026)</em></p><p>帕金森病的分子病理核心是 α-突触核蛋白（α-Syn）的错误折叠聚集，但血液检测一直被红血球来源的大量外周 α-Syn 背景所淹没。研究团队转向血液中&quot;神经元来源的胞外囊泡（EV）&quot;——一个生物学上更富集脑源性 α-Syn 的稀缺来源，用有机电化学晶体管实现多参数电子剖析。该器件绕开了超低丰度带来的信噪比难题，把神经源 EV 的电学指纹转化为可判读的疾病信号，展示出早期预测帕金森病的可能，为无创、廉价的神经退行性疾病筛查打开一条电学路径。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aee4525" target="_blank" rel="noreferrer">10.1126/sciadv.aee4525</a></p><hr><h3 id="🧲-双共线反铁磁体中反常霍尔效应的非单调标度" tabindex="-1">🧲 双共线反铁磁体中反常霍尔效应的非单调标度 <a class="header-anchor" href="#🧲-双共线反铁磁体中反常霍尔效应的非单调标度" aria-label="Permalink to &quot;🧲 双共线反铁磁体中反常霍尔效应的非单调标度&quot;">​</a></h3><p><strong>Nonmonotonic scaling of the anomalous Hall effect in a bicollinear antiferromagnet</strong><em>Science Advances (2026)</em></p><p>在没有净磁化的反铁磁体系中观察到反常霍尔效应（AHE），对基础物理与自旋电子学都极具价值。二维范德华反铁磁体碲化铁（FeTe）拥有罕见的&quot;磁补偿双共线反铁磁&quot;结构，并被认为存在导致强关联的 Kondo 相互作用。研究聚焦 AHE 随温度、载流子浓度的标度行为，发现其呈现<strong>非单调</strong>变化——而非简单的线性或单调依赖。这种非单调标度指向多个机制（贝里曲率、Kondo 散射、磁结构涨落）之间的竞争与交叉，为理解磁补偿反铁磁体中的输运提供了关键实验标尺，也提示其在低功耗自旋器件中的可调性。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aef9859" target="_blank" rel="noreferrer">10.1126/sciadv.aef9859</a></p><hr><h3 id="🌾-深度学习化石花粉形态-重建东非草原-25000-年生态变迁" tabindex="-1">🌾 深度学习化石花粉形态，重建东非草原 25000 年生态变迁 <a class="header-anchor" href="#🌾-深度学习化石花粉形态-重建东非草原-25000-年生态变迁" aria-label="Permalink to &quot;🌾 深度学习化石花粉形态，重建东非草原 25000 年生态变迁&quot;">​</a></h3><p><strong>Deep learning of fossil pollen morphology reveals 25,000 y of ecological change in eastern African grasslands</strong><em>PNAS (2026)</em></p><p>禾本科（Poaceae）花粉因光学显微镜下多数物种无法区分，长期在草原演化研究中被忽视。Adaimé 等把超分辨显微成像与深度学习结合起来：用半监督策略，在已知现代花粉与未标注化石花粉的超分辨图像上训练卷积神经网络（CNN），再用学到的 CNN 特征估计分类学多样性，量化禾本科花粉间被传统方法抹平的形态变异。该方法把&quot;看不见的多样性&quot;变成可统计的时间序列，重建出东非草原过去 25000 年的生态变化，为古生态学提供了一条不依赖形态学专家经验的自动化路径。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2607372123" target="_blank" rel="noreferrer">10.1073/pnas.2607372123</a></p><hr><h3 id="⚛️-两个质子、两个正电子与四个电子-兼具范德华特征的共价键" tabindex="-1">⚛️ 两个质子、两个正电子与四个电子：兼具范德华特征的共价键 <a class="header-anchor" href="#⚛️-两个质子、两个正电子与四个电子-兼具范德华特征的共价键" aria-label="Permalink to &quot;⚛️ 两个质子、两个正电子与四个电子：兼具范德华特征的共价键&quot;">​</a></h3><p><strong>Two protons, two positrons, and four electrons: Covalent bond with van der Waals characteristics</strong><em>Science Advances (2026)</em></p><p>物质—反物质体系的成键机制一直是谜。研究对象是氢化正电子素（PsH）二聚体——由两个质子、两个正电子与四个电子构成，其键合性质过去被不同地描述为离子键、共价键或范德华作用。研究通过高精度量子化学计算，精确刻画了这一体系的电子结构，得出其键合<strong>兼具共价性质与范德华特征</strong>的结论。这项工作把&quot;键&quot;的分类边界从常规物质拓展到反物质参与的体系，为理解正电子素化学（positronium chemistry）提供了定量基准，也关系到正电子湮没谱学等实验解读。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aej0387" target="_blank" rel="noreferrer">10.1126/sciadv.aej0387</a></p>',28)])])}const u=a(n,[["render",s]]);export{g as __pageData,u as default};
